import React, { useEffect, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { createClient } from '@supabase/supabase-js';
import { BrowserMultiFormatReader } from '@zxing/browser';
import './style.css';
import './family.css';
import './journey.css';
import './checkin.css';
import programs from './programs.json';
import './progress.css';
import './program.css';
import {workoutPlans,workoutFor} from './workouts.js';
import './workout.css';
import './management.css';
import './calendar.css';
import './calendar-choices.css';
import './profile.css';
import './no-icloud.css';
import './home.css';
import './room-tabs.css';
import './relocation.css';
import './navigation-fix.css';
import './home-sync.css';
import './reminders.css';
import './family-dashboard.css';
import './planner.css';
