function DeviceAdmin(){const[available,setAvailable]=useState([]);const[selected,setSelected]=useState([]);const[msg,setMsg]=useState('');async function call(action,extra={}){const{data:{session}}=await supabase.auth.getSession();return fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/ft-home-assistant`,{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json'},body:JSON.stringify({action,...extra})}).then(r=>r.json())}async function discover(){setMsg('Finding devices and areas…');const[current,list]=await Promise.all([call('states'),call('available')]);if(list.error)setMsg(list.error);else{setAvailable(list.entities);setSelected((current.entities||[]).map(e=>e.entity_id));setMsg('')}}async function save(){const x=await call('save',{entities:available.filter(e=>selected.includes(e.entity_id))});setMsg(x.error||'Allowed devices and room assignments saved.')}return <div className="page adminextra"><section className="panel admin-device-config"><div className="choicehead"><div><h2>Home Assistant devices</h2><p>Choose the lights, switches, and scenes available to the family. The Home Assistant area helps distinguish similar names.</p></div><button className="primary" onClick={discover}>Find devices</button></div>{available.length>0&&<><div className="checkgrid">{available.map(e=><label key={e.entity_id}><input type="checkbox" checked={selected.includes(e.entity_id)} onChange={()=>setSelected(s=>s.includes(e.entity_id)?s.filter(x=>x!==e.entity_id):[...s,e.entity_id])}/><span/><div className="devicechoice"><strong>{e.name}</strong><small>{e.area||'No area assigned'}</small></div></label>)}</div><button className="primary savehome" onClick={save}>Save allowed devices</button></>}{msg&&<p className="message status">{msg}</p>}</section></div>}
function CalendarPreferences(){const[calendars,setCalendars]=useState([]);const[selected,setSelected]=useState([]);const[msg,setMsg]=useState('');async function call(action,extra={}){const{data:{session}}=await supabase.auth.getSession();return fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/ft-google-calendar`,{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json'},body:JSON.stringify({action,...extra})}).then(r=>r.json())}useEffect(()=>{call('events').then(x=>{setCalendars(x.calendars||[]);setSelected(x.selected_calendar_ids||[])})},[]);async function save(){const x=await call('save_calendars',{calendar_ids:selected});setMsg(x.error||'Visible calendars saved.')}return <div className="page personalcal"><section className="panel"><p className="kicker">CALENDAR SETTINGS</p><div className="choicehead"><div><h2>Visible calendars</h2><p>These choices apply only to your calendar view.</p></div><button className="primary" onClick={save}>Save choices</button></div><div className="checkgrid">{calendars.map(c=><label key={c.id}><input type="checkbox" checked={selected.includes(c.id)} onChange={()=>setSelected(s=>s.includes(c.id)?s.filter(x=>x!==c.id):[...s,c.id])}/><span style={{background:c.color}}/><strong>{c.name}</strong>{c.primary&&<small>Primary</small>}</label>)}</div>{msg&&<p className="message status">{msg}</p>}</section></div>}
