function UnifiedHomeHub(){const[state,setState]=useState({entities:[]});const[room,setRoom]=useState('All');const[levels,setLevels]=useState({});const[msg,setMsg]=useState('');async function call(action,extra={}){const{data:{session}}=await supabase.auth.getSession();return fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/ft-home-assistant`,{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json'},body:JSON.stringify({action,...extra})}).then(r=>r.json())}async function load(){const x=await call('states');if(x.error)setMsg(x.error);else{setState(x);setLevels(Object.fromEntries((x.entities||[]).map(e=>[e.entity_id,e.brightness||0])))}}useEffect(()=>{load()},[]);async function control(id){const x=await call('control',{entity_id:id});setMsg(x.error||'Command sent.');if(!x.error)setTimeout(load,350)}async function brightness(id,value){setLevels(v=>({...v,[id]:Number(value)}));const x=await call('control',{entity_id:id,brightness_pct:Number(value)});setMsg(x.error||'Brightness updated.');if(!x.error)setTimeout(load,250)}const rooms=['All',...new Set(state.entities.map(e=>e.room||'Other'))];const visible=room==='All'?state.entities:state.entities.filter(e=>(e.room||'Other')===room);const lights=visible.filter(e=>e.domain==='light'&&e.supports_brightness);return <div className="page"><p className="kicker">SMART HOME</p><h1>Home, within reach.</h1><p className="lead">Approved controls organized by room.</p>{msg&&<p className="message status">{msg}</p>}{state.entities.length>0&&<div className="roomtabs">{rooms.map(r=><button className={room===r?'active':''} onClick={()=>setRoom(r)} key={r}>{r} <small>{r==='All'?state.entities.length:state.entities.filter(e=>(e.room||'Other')===r).length}</small></button>)}</div>}<div className="devicegrid">{visible.map(e=><button className={`device ${e.state==='on'?'on':''}`} onClick={()=>control(e.entity_id)} key={e.entity_id}><span>{e.domain==='light'?'●':e.domain==='scene'?'▶':'◆'}</span><strong>{e.display_name}</strong><small>{e.domain==='scene'?'Run scene':e.state} · {e.room||'Other'}</small></button>)}</div>{lights.length>0&&<section className="panel roombBrightness"><p className="kicker">{room==='All'?'ALL ROOMS':room.toUpperCase()}</p><h2>Brightness</h2><div className="brightnessgrid">{lights.map(l=><label key={l.entity_id}><div><strong>{l.display_name}</strong><small>{l.room||'Other'}</small></div><input type="range" min="1" max="100" value={levels[l.entity_id]||1} onChange={e=>brightness(l.entity_id,e.target.value)}/><b>{levels[l.entity_id]||0}%</b></label>)}</div></section>}</div>}
