function urlBase64ToUint8Array(value){const padding='='.repeat((4-value.length%4)%4);const base64=(value+padding).replace(/-/g,'+').replace(/_/g,'/');return Uint8Array.from(atob(base64),c=>c.charCodeAt(0))}
function ReminderPreferences({household,session}){const defaults={checkin_enabled:false,checkin_time:'19:30',workout_enabled:false,workout_time:'07:00',weekly_review_enabled:false,weekly_review_day:0,weekly_review_time:'18:00',encouragement_enabled:false,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'America/Chicago'};const[prefs,setPrefs]=useState(defaults);const[msg,setMsg]=useState('');const[permission,setPermission]=useState(typeof Notification==='undefined'?'unsupported':Notification.permission);const installed=window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true;async function call(action){const{data:{session:s}}=await supabase.auth.getSession();return fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/ft-notifications`,{method:'POST',headers:{Authorization:`Bearer ${s.access_token}`,'Content-Type':'application/json'},body:JSON.stringify({action})}).then(r=>r.json())}useEffect(()=>{supabase.from('ft_notification_preferences').select('*').eq('household_id',household.id).eq('user_id',session.user.id).maybeSingle().then(({data})=>data&&setPrefs({...defaults,...data,checkin_time:data.checkin_time?.slice(0,5),workout_time:data.workout_time?.slice(0,5),weekly_review_time:data.weekly_review_time?.slice(0,5)}))},[household.id,session.user.id]);async function save(){setMsg('Saving…');const payload={...prefs,household_id:household.id,user_id:session.user.id,updated_at:new Date().toISOString()};delete payload.last_checkin_sent_at;delete payload.last_workout_sent_at;delete payload.last_weekly_review_sent_at;const{error}=await supabase.from('ft_notification_preferences').upsert(payload);setMsg(error?error.message:'Reminder choices saved.')}async function enable(){try{setMsg('Connecting this device…');const result=await call('public_key');if(result.error)throw new Error(result.error);const allowed=await Notification.requestPermission();setPermission(allowed);if(allowed!=='granted')throw new Error('Notifications were not allowed on this device.');const registration=await navigator.serviceWorker.ready;const subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBase64ToUint8Array(result.public_key)});const value=subscription.toJSON();const{error}=await supabase.from('ft_push_subscriptions').upsert({household_id:household.id,user_id:session.user.id,endpoint:value.endpoint,p256dh:value.keys.p256dh,auth_key:value.keys.auth,user_agent:navigator.userAgent,updated_at:new Date().toISOString()},{onConflict:'endpoint'});if(error)throw error;setMsg('Notifications enabled on this device.')}catch(error){setMsg(error.message||'Notifications could not be enabled.')}}async function test(){setMsg('Sending test…');const result=await call('test');setMsg(result.error||'Test reminder sent.')}const set=(key,value)=>setPrefs(p=>({...p,[key]:value}));return <div className="page reminderpage"><section className="panel"><div className="reminderhead"><div><p className="kicker">REMINDERS</p><h2>A gentle nudge at the right time</h2><p>Every family member chooses their own reminders.</p></div><span className={`reminderstatus ${permission==='granted'?'on':''}`}>● {permission==='granted'?'Enabled here':'Not enabled'}</span></div>{!installed&&/iPhone|iPad|iPod/.test(navigator.userAgent)&&<p className="installnote">On iPhone or iPad: tap Share, choose Add to Home Screen, then open Faithful Together from its new icon before enabling reminders.</p>}<div className="remindergrid"><div className="reminderrow"><label><input type="checkbox" checked={prefs.workout_enabled} onChange={e=>set('workout_enabled',e.target.checked)}/><span><strong>Workout reminder</strong><small>Start the day with your planned movement.</small></span></label><input type="time" value={prefs.workout_time} onChange={e=>set('workout_time',e.target.value)}/></div><div className="reminderrow"><label><input type="checkbox" checked={prefs.checkin_enabled} onChange={e=>set('checkin_enabled',e.target.checked)}/><span><strong>Evening check-in</strong><small>Record the day before it gets away.</small></span></label><input type="time" value={prefs.checkin_time} onChange={e=>set('checkin_time',e.target.value)}/></div><div className="reminderrow"><label><input type="checkbox" checked={prefs.weekly_review_enabled} onChange={e=>set('weekly_review_enabled',e.target.checked)}/><span><strong>Weekly review</strong><small>Notice progress and prepare the next week.</small></span></label><div><select value={prefs.weekly_review_day} onChange={e=>set('weekly_review_day',Number(e.target.value))}>{['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((day,index)=><option value={index} key={day}>{day}</option>)}</select><input type="time" value={prefs.weekly_review_time} onChange={e=>set('weekly_review_time',e.target.value)}/></div></div></div><div className="reminderactions"><button className="primary" onClick={save}>Save reminders</button><button onClick={enable}>Enable on this device</button>{permission==='granted'&&<button onClick={test}>Send test reminder</button>}</div>{msg&&<p className="message status">{msg}</p>}</section></div>}
