function FamilyDashboard({household}){const[members,setMembers]=useState([]);const[cheers,setCheers]=useState([]);const[msg,setMsg]=useState('');async function load(){const[{data:m,error},{data:c},people]=await Promise.all([supabase.rpc('ft_family_dashboard',{target_household:household.id}),supabase.from('ft_family_encouragements').select('*').eq('household_id',household.id).order('created_at',{ascending:false}).limit(6),loadMembers(household.id)]);if(error)setMsg(error.message);else setMembers(m||[]);const names=Object.fromEntries(people.map(p=>[p.user_id,p.display_name||'Family member']));setCheers((c||[]).map(x=>({...x,from_name:names[x.from_user_id],to_name:names[x.to_user_id]})))}useEffect(()=>{load()},[household.id]);async function cheer(member){const{data:{user}}=await supabase.auth.getUser();const{error}=await supabase.from('ft_family_encouragements').insert({household_id:household.id,from_user_id:user.id,to_user_id:member.user_id,message:'Way to stay faithful!'});setMsg(error?error.message:`Encouragement sent to ${member.display_name}.`);if(!error)load()}const shared=members.filter(m=>m.progress_shared||m.is_self);const faithful=shared.reduce((sum,m)=>sum+(m.faithful_last_7||0),0);const goal=Math.max(1,shared.length*5);const percent=Math.min(100,Math.round(faithful/goal*100));return <div className="page"><p className="kicker">OUR HOUSEHOLD</p><h1>{household.name}</h1><p className="lead">Celebrate faithfulness. Support one another. Keep personal details personal.</p><section className="familyhero"><div><p className="kicker">SHARED WEEKLY MOMENTUM</p><h2>{faithful} faithful days together</h2><p>A family goal of {goal} faithful days this week—steady effort, not perfection.</p><div className="momentum"><span style={{width:`${percent}%`}}/></div></div><aside><div><strong>{percent}%</strong><span>toward the family goal</span></div></aside></section><div className="familycards">{members.map(m=><article className="familycard" key={m.user_id}><div className="familycardtop"><span className="avatar">{(m.display_name||'M')[0]}</span><div><h3>{m.display_name}</h3><p>{m.life_stage}{m.is_self?' · You':''}</p></div></div>{m.progress_shared||m.is_self?<><div className="familymetrics"><div><strong>{m.current_streak}</strong><span>day streak</span></div><div><strong>{m.faithful_last_7}/7</strong><span>this week</span></div></div>{m.daily_shared||m.is_self?<p className={`todaybadge ${m.today_complete?'':'waiting'}`}>{m.today_complete?'✓ Today completed':'○ Still building today'}</p>:<p className="todaybadge waiting">Today’s status is private</p>}</>:<div className="privatecard">Progress is private.<br/>Cheering is always welcome.</div>}{!m.is_self&&<button className="cheerbutton" onClick={()=>cheer(m)}>Send encouragement</button>}</article>)}</div>{cheers.length>0&&<section className="panel"><h2>Family celebrations</h2><div className="cheerfeed">{cheers.map(c=><div className="cheeritem" key={c.id}><span>◆</span><div><p><strong>{c.from_name||'Family'}</strong> to {c.to_name||'a family member'}: {c.message}</p><small>{new Date(c.created_at).toLocaleDateString()}</small></div></div>)}</div></section>}{msg&&<p className="message status">{msg}</p>}</div>}
function PrivacySettings({household,session}){const[state,setState]=useState({share_progress_to_household:true,share_daily_completion:true});const[msg,setMsg]=useState('');useEffect(()=>{supabase.from('ft_member_settings').select('share_progress_to_household,share_daily_completion').eq('household_id',household.id).eq('user_id',session.user.id).single().then(({data})=>data&&setState(data))},[household.id,session.user.id]);async function save(){const{error}=await supabase.from('ft_member_settings').update({...state,updated_at:new Date().toISOString()}).eq('household_id',household.id).eq('user_id',session.user.id);setMsg(error?error.message:'Family sharing choices saved.')}return <div className="page reminderpage"><section className="panel"><p className="kicker">FAMILY PRIVACY</p><h2>Choose what the family can celebrate</h2><p>Your journal, weight, steps, sleep, and other health details always remain private.</p><div className="privacygrid"><label><input type="checkbox" checked={state.share_progress_to_household} onChange={e=>setState({...state,share_progress_to_household:e.target.checked})}/><span><strong>Share streak and weekly progress</strong><small>Shows only completion counts—never health numbers.</small></span></label><label><input type="checkbox" checked={state.share_daily_completion} onChange={e=>setState({...state,share_daily_completion:e.target.checked})}/><span><strong>Share today’s completion</strong><small>Shows whether today is complete, without the details.</small></span></label></div><button className="primary" onClick={save}>Save privacy choices</button>{msg&&<p className="message status">{msg}</p>}</section></div>}
