  async function load(){const[{data:m,error},{data:c},people]=await Promise.all([supabase.rpc('ft_family_dashboard',{target_household:household.id}),supabase.from('ft_family_encouragements').select('*').eq('household_id',household.id).order('created_at',{ascending:false}).limit(6),loadMembers(household.id)]);if(error)setMsg(error.message);else setMembers(m||[]);const names=Object.fromEntries(people.map(p=>[p.user_id,p.display_name||'Family member']));setCheers((c||[]).map(x=>({...x,from_name:names[x.from_user_id],to_name:names[x.to_user_id]})))}
  useEffect(()=>{load()},[household.id]);
