  const shared=members.filter(m=>m.progress_shared||m.is_self);const faithful=shared.reduce((sum,m)=>sum+(m.faithful_last_7||0),0);const goal=Math.max(1,shared.length*5);const percent=Math.min(100,Math.round(faithful/goal*100));
  return <div className="page"><p className="kicker">OUR HOUSEHOLD</p><h1>{household.name}</h1><p className="lead">Celebrate faithfulness. Support one another. Keep personal details personal.</p><section className="familyhero"><div><p className="kicker">SHARED WEEKLY MOMENTUM</p><h2>{faithful} faithful days together</h2><p>A family goal of {goal} faithful days this week—steady effort, not perfection.</p><div className="momentum"><span style={{width:`${percent}%`}}/></div></div><aside><div><strong>{percent}%</strong><span>toward the family goal</span></div></aside></section><div className="familycards">{members.map(m=><article className="familycard" key={m.user_id}><div className="familycardtop"><span className="avatar">{(m.display_name||'M')[0]}</span><div><h3>{m.display_name}</h3><p>{m.life_stage}{m.is_self?' · You':''}</p></div></div>{m.progress_shared||m.is_self?<><div className="familymetrics"><div><strong>{m.current_streak}</strong><span>day streak</span></div><div><strong>{m.faithful_last_7}/7</strong><span>this week</span></div></div>{m.daily_shared||m.is_self?<p className={`todaybadge ${m.today_complete?'':'waiting'}`}>{m.today_complete?'✓ Today completed':'○ Still building today'}</p>:<p className="todaybadge waiting">Today’s status is private</p>}</>:<div className="privatecard">Progress is private.<br/>Cheering is always welcome.</div>}{!m.is_self&&(choosing===m.user_id?<div className="cheerchoices">{messages.map(x=><button onClick={()=>cheer(m,x)} key={x}>{x}</button>)}<button className="cheercancel" onClick={()=>setChoosing(null)}>Cancel</button></div>:<button className="cheerbutton" onClick={()=>setChoosing(m.user_id)}>Send encouragement</button>)}</article>)}</div>{cheers.length>0&&<section className="panel"><h2>Family celebrations</h2><div className="cheerfeed">{cheers.map(c=><div className="cheeritem" key={c.id}><span>◆</span><div><p><strong>{c.from_name||'Family'}</strong> to {c.to_name||'a family member'}: {c.message}</p><small>{new Date(c.created_at).toLocaleDateString()}</small></div></div>)}</div></section>}{msg&&<p className="message status">{msg}</p>}</div>;
