function BarcodeScanner({household,onLogged}){
  const[code,setCode]=useState(''),[scanning,setScanning]=useState(false),[food,setFood]=useState(null),[qty,setQty]=useState(1),[meal,setMeal]=useState('snack'),[msg,setMsg]=useState('');
  const video=React.useRef(null),controls=React.useRef(null),found=React.useRef(false);
  useEffect(()=>{
    if(!scanning)return;
    let cancelled=false;
    found.current=false;
    const reader=new BrowserMultiFormatReader();
    (async()=>{try{
      controls.current=await reader.decodeFromConstraints({video:{facingMode:{ideal:'environment'}}},video.current,(result)=>{
        if(result&&!found.current){found.current=true;lookup(result.getText())}
      });
      if(cancelled)controls.current?.stop();
    }catch(error){
      if(!cancelled){setScanning(false);setMsg('Camera scanning is unavailable. Enter the barcode number below.')}
    }})();
    return()=>{cancelled=true;controls.current?.stop();controls.current=null};
  },[scanning]);
  async function lookup(value=code){const clean=String(value).replace(/\D/g,'');if(!clean)return;controls.current?.stop();setScanning(false);setCode(clean);setMsg('Looking up barcode…');const{data:{session}}=await supabase.auth.getSession();const x=await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/ft-barcode-search`,{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json'},body:JSON.stringify({barcode:clean})}).then(r=>r.json());setFood(x.food||null);setMsg(x.error||'')}
  function start(){setFood(null);setMsg('Point the camera at the barcode.');setScanning(true)}
  async function log(){const{data:{user}}=await supabase.auth.getUser();const{error}=await supabase.from('ft_food_logs').insert({household_id:household.id,user_id:user.id,logged_on:localDateKey(),meal,food_name:food.name,source:food.source,source_id:String(food.id),serving_label:food.serving_label,quantity:qty,calories:food.calories*qty,protein_g:food.protein_g*qty,carbs_g:food.carbs_g*qty,fat_g:food.fat_g*qty});setMsg(error?error.message:'Scanned food logged.');if(!error){setFood(null);setCode('');onLogged()}}
  return <div className="page barcodepage"><section className="panel"><p className="kicker">BARCODE SCANNER</p><h2>Scan a packaged food</h2><p>We check USDA first, then Open Food Facts when needed. Confirm the label before logging.</p><div className="barcodeactions"><button className="primary" onClick={scanning?()=>setScanning(false):start}>{scanning?'Stop camera':'Scan barcode'}</button><input inputMode="numeric" value={code} onChange={e=>setCode(e.target.value)} placeholder="Or enter barcode number"/><button onClick={()=>lookup()}>Look up</button></div>{scanning&&<div className="scannerbox"><video ref={video} muted playsInline autoPlay/></div>}{food&&<div className="scanresult"><span className="scansource">{food.source}</span><h3>{food.name}</h3><p>{food.brand}{food.brand?' · ':''}{food.serving_label}</p><p>{Math.round(food.calories)} cal · {food.protein_g.toFixed(1)}g protein · {food.carbs_g.toFixed(1)}g carbs · {food.fat_g.toFixed(1)}g fat</p><div className="scancontrols"><label>Servings<input type="number" min=".1" step=".1" value={qty} onChange={e=>setQty(Number(e.target.value))}/></label><label>Meal<select value={meal} onChange={e=>setMeal(e.target.value)}>{['breakfast','lunch','dinner','snack','meal'].map(x=><option key={x}>{x}</option>)}</select></label><button className="primary" onClick={log}>Log food</button></div></div>}{msg&&<p className="message status">{msg}</p>}</section></div>
}
const NutritionBeforeBarcode=Nutrition;
function NutritionWithBarcode(props){const[version,setVersion]=useState(0);return <><BarcodeScanner household={props.household} onLogged={()=>setVersion(x=>x+1)}/><NutritionBeforeBarcode key={version} {...props}/></>}
