  if(!data)return <div className="page loadingpane">Preparing your weekly review…</div>;
  const faithful=data.checks.filter(x=>['complete','modified'].includes(x.status)).length,avg=(k)=>{const xs=data.checks.map(x=>Number(x[k])).filter(Boolean);return xs.length?Math.round(xs.reduce((a,b)=>a+b,0)/xs.length):0},foodDays=new Set(data.foods.map(x=>x.logged_on)).size,waterTotal=data.water.reduce((s,x)=>s+Number(x.ounces),0),weights=data.checks.filter(x=>x.weight_lbs!=null),weightChange=weights.length>1?(Number(weights[0].weight_lbs)-Number(weights.at(-1).weight_lbs)).toFixed(1):null;
  const priorities=[];if(faithful<5)priorities.push('Use a lower-intensity or recovery day before the plan becomes all-or-nothing.');else priorities.push('Protect the routines that produced this steady week.');if(avg('steps')<(data.settings.step_goal||7000)*.8)priorities.push('Schedule one reliable walking window each day.');else priorities.push('Keep your current step rhythm and recover well.');if(foodDays<5)priorities.push('Log one repeatable meal each day—clarity matters more than perfect detail.');else priorities.push('Prepare or favorite two meals that made nutrition easier.');if(avg('sleep_minutes')<(data.settings.sleep_goal_minutes||420))priorities[2]='Protect a consistent bedtime on at least five nights.';
