const SettingsBeforeHealthSync=Settings;
function HealthStepSync(){
  const[state,setState]=useState({connected:false,last_used_at:null,last_merge:null}),[setup,setSetup]=useState(null),[msg,setMsg]=useState('');
  async function call(action){const{data:{session}}=await supabase.auth.getSession();return fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/ft-health-steps`,{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json'},body:JSON.stringify({action})}).then(r=>r.json())}
  async function load(){const x=await call('status');if(!x.error)setState(x)}
  useEffect(()=>{load()},[]);
  async function create(){setMsg('Creating private connection…');const x=await call('create');if(x.error)setMsg(x.error);else{setSetup(x);setState({connected:true,last_used_at:null});setMsg('Connection created. Keep this page open while we build the Shortcut.')}}
  async function revoke(){if(!window.confirm('Disconnect Apple Health step imports? Your existing step history will remain.'))return;const x=await call('revoke');setSetup(null);setState({connected:false,last_used_at:null});setMsg(x.error||'Apple Health step import disconnected.')}
  const publicImportUrl=`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/ft-health-steps`;
  return <div className="page healthsync"><section className="panel"><p className="kicker">APPLE HEALTH STEPS</p><h2>Bring daily steps into Faithful Together</h2><p>Your private Shortcut can use Apple Watch only, or Faithful Merge can combine Watch and iPhone samples without counting the same five-minute window twice.</p><p className={`healthstatus ${state.connected?'on':''}`}>● {state.connected?'Connection ready':'Not connected'}</p>{state.last_used_at&&<p className="synclast">Last synced {new Date(state.last_used_at).toLocaleString()}</p>}{state.last_merge&&<div className="mergeproof"><div><strong>{Number(state.last_merge.steps).toLocaleString()}</strong><span>Faithful merged</span></div><div><strong>{Number(state.last_merge.steps_watch||0).toLocaleString()}</strong><span>Watch raw</span></div><div><strong>{Number(state.last_merge.steps_phone||0).toLocaleString()}</strong><span>iPhone raw</span></div><p>Overlap removed across {state.last_merge.steps_overlap_buckets||0} five-minute windows.</p></div>}<div className="healthactions">{!state.connected&&<button className="primary" onClick={create}>Create my connection</button>}{state.connected&&!setup&&<button onClick={create}>Replace connection code</button>}{state.connected&&<button onClick={revoke}>Disconnect</button>}</div>{setup&&<div className="syncsecret"><strong>One-time connection code</strong><code>{setup.connection_code}</code><p>This code is shown only now. Do not share it; it can update your step count.</p><strong>Shortcut web address</strong><code>{publicImportUrl}</code></div>}<ol className="shortcutsteps"><li>Watch-only sync remains available as the dependable baseline.</li><li>Faithful Merge accepts timestamped Watch and iPhone samples.</li><li>For every five-minute window, it keeps the higher source instead of adding both.</li></ol>{msg&&<p className="message status">{msg}</p>}</section></div>
}
function SettingsWithHealthSync(props){return <><SettingsBeforeHealthSync {...props}/><HealthStepSync/></>}
Settings=SettingsWithHealthSync;
